export default async function PrivacyPolicyPage() {
    const operator = await getOperatorInfo();
    return (
        <LegalPage
            current="/privacy-policy"
            eyebrow={{ TR: "Gizlilik ve veri koruma", EN: "Privacy and data protection" }}
            title={{ TR: "Gizlilik Politikası", EN: "Privacy Policy" }}
            summary={{ TR: "Hanogt Codev'i kullanırken hangi kişisel verilerinizin neden işlendiğini, nereye gittiğini, ne kadar saklandığını ve verileriniz üzerindeki haklarınızı nasıl kullanabileceğinizi sade bir dille anlatır.", EN: "Explains in plain language which of your personal data is processed when you use Hanogt Codev and why, where it goes, how long it is kept and how you can exercise your rights over it." }}
            sections={sections(operator)}
            highlights={highlights}
            operator={operator}
            notice={isOperatorPublished(operator)
                ? { TR: "Ödemeler, Kayıtlı Satıcımız Paddle tarafından alınır; kart bilgileriniz Hanogt Codev'e ulaşmaz. Veri sorumlusunun kimlik ve iletişim bilgileri sayfanın başındaki kartta ve [veri sorumlusu](/privacy-policy#controller) bölümünde yer alır.", EN: "Payments are taken by Paddle, our Merchant of Record; your card details never reach Hanogt Codev. The data controller's identity and contact details are in the card at the top of the page and in the [data controller](/privacy-policy#controller) section." }
                : { TR: "Veri sorumlusunun ticari unvanı, MERSİS/VKN, adresi ve KEP adresi henüz yayımlanmamıştır; yayımlandığında bu metin güncellenecektir. O zamana kadar tüm başvurular uygulama içindeki destek talebi kanalından alınır.", EN: "The data controller's trade name, MERSİS/tax number, address and registered e-mail (KEP) address have not been published yet; this text will be updated when they are. Until then, all requests are received through the in-app support ticket channel." }}
        />
    );
}
